#!/usr/bin/env node
// Generate the pdf.js worker Sard actually loads: the compatibility layer, then the vendored worker.
//
// WHY A GENERATED FILE RATHER THAN AN IMPORT. The worker needs the three polyfills installed before a
// single line of `pdf.worker.mjs` evaluates, and a worker is its own realm — the copy loaded into the
// page from `index.html` does not reach it. Three deliveries were considered:
//
//   blob: URL wrapper      REFUSED BY THE APP'S OWN CSP. Measured: `script-src 'self'` rejects it with
//                          "Failed to fetch dynamically imported module: blob:…". Not a maybe.
//   a wrapper that does    Plausible, and probably fine — but `pdf.worker.mjs` contains ZERO static
//   two static imports     imports, so nothing in the shipped tree exercises module-import-inside-a-
//                          worker under this CSP, and it would be the first thing to do so.
//   CONCATENATION (this)   No import, no new CSP surface, nothing to resolve at run time. The worker is
//                          one file, exactly as it is today, with 60 lines in front of it.
//
// The third is chosen because it adds no mechanism that could fail. It is also the only one that keeps
// working if the CSP is ever tightened further.
//
// THE VENDORED FILE IS NOT EDITED. It is read and copied. `public/foliate-js/vendor/pdfjs/` stays
// byte-identical to upstream, which is the rule VENDOR.txt exists to enforce — a re-vendor overwrites
// that directory and this script simply regenerates from whatever is there.
//
// WHY THE OUTPUT SITS BESIDE THE ORIGINAL. `pdf.worker.mjs` reads `import.meta.url` twice to locate its
// own resources. Generating the bundle into the same directory keeps that resolution identical; moving
// it one level up would silently change where the worker looks for its assets.
//
// The output is generated, not tracked (see .gitignore). It is produced by `npm run dev` and by
// `npm run build`, so every path that serves the frontend has it — a build is the only way the app is
// ever run, and there is no arrangement in which the file is missing while pdf.js is present.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";

const ROOT = join(import.meta.dirname, "..");
const PDFJS = join(ROOT, "public", "foliate-js", "vendor", "pdfjs");
const POLYFILL = join(ROOT, "public", "foliate-js", "sard-pdf-polyfill.mjs");
const SOURCE = join(PDFJS, "pdf.worker.mjs");
const OUT = join(PDFJS, "pdf.worker.sard.mjs");

for (const [label, path] of [["compatibility layer", POLYFILL], ["vendored worker", SOURCE]]) {
  if (!existsSync(path)) {
    console.error(`\n  build-pdf-worker: the ${label} is missing at ${path}\n`);
    process.exit(1);
  }
}

const polyfill = readFileSync(POLYFILL, "utf8");
const worker = readFileSync(SOURCE, "utf8");

// A banner, because this file is large, generated, and will be opened by someone wondering why the
// worker looks unfamiliar. It says where to make a change so nobody edits the output.
const banner = [
  "// GENERATED BY scripts/build-pdf-worker.mjs — DO NOT EDIT.",
  "//",
  "// This is public/foliate-js/vendor/pdfjs/pdf.worker.mjs, unmodified, with Sard's PDF compatibility",
  "// layer (public/foliate-js/sard-pdf-polyfill.mjs) placed in front of it so the three built-ins",
  "// pdf.js assumes exist are installed in the WORKER realm before pdf.js evaluates.",
  "//",
  "// Edit the polyfill or re-run the build. Editing this file achieves nothing: it is overwritten.",
  "",
].join("\n");

writeFileSync(OUT, `${banner}${polyfill}\n${worker}`, "utf8");

const kb = (s) => `${Math.round(s.length / 1024)} KB`;
console.log(`  pdf worker: ${kb(polyfill)} compatibility layer + ${kb(worker)} vendored worker -> pdf.worker.sard.mjs`);
